export const week07Questions: QuizQuestion[] = [
  { id: 'w7q1', week: 7, type: 'multiple_choice', question: 'What annotation marks a class as a JPA entity?', options: ['@Table', '@Entity', '@Model', '@Record'], correctAnswer: '@Entity', explanation: '@Entity marks a class as a JPA entity mapped to a database table. @Table optionally specifies the table name.' },
  { id: 'w7q2', week: 7, type: 'true_false', question: '@OneToMany means one entity has a collection of related entities.', correctAnswer: 'True', explanation: '@OneToMany defines a one-to-many relationship, e.g., one Author has many Books. The "many" side usually has the foreign key.' },
  { id: 'w7q3', week: 7, type: 'multiple_choice', question: 'What does JpaRepository provide?', options: ['Only save()', 'Built-in CRUD operations and query derivation', 'Only findAll()', 'Database migration'], correctAnswer: 'Built-in CRUD operations and query derivation', explanation: 'JpaRepository provides save, findById, findAll, delete, and automatic query generation from method names like findByName().' },
  { id: 'w7q4', week: 7, type: 'fill_blank', question: 'A SQL _____ JOIN returns only matching rows from both tables.', correctAnswer: 'INNER', explanation: 'INNER JOIN returns rows where there\'s a match in both tables. LEFT JOIN includes all left-table rows even without matches.' },
  { id: 'w7q5', week: 7, type: 'code_snippet', question: 'What query does Spring Data generate from this method?', codeSnippet: 'List<User> findByLastNameAndAgeGreaterThan(\n  String lastName, int age);', options: ['SELECT * FROM user', 'SELECT * FROM user WHERE last_name = ? AND age > ?', 'SELECT * FROM user WHERE last_name > ?', 'It won\'t work'], correctAnswer: 'SELECT * FROM user WHERE last_name = ? AND age > ?', explanation: 'Spring Data JPA derives queries from method names. "findBy" starts the query, "LastName" is a field, "And" joins conditions, "GreaterThan" is > operator.' },
  { id: 'w7q6', week: 7, type: 'multiple_choice', question: 'What is Flyway used for?', options: ['Testing', 'Database schema migrations', 'Caching', 'Security'], correctAnswer: 'Database schema migrations', explanation: 'Flyway manages database schema changes through versioned migration scripts, ensuring consistent schema across environments.' },
  { id: 'w7q7', week: 7, type: 'true_false', question: 'H2 is an in-memory database suitable for production use.', correctAnswer: 'False', explanation: 'H2 is great for development and testing (fast, no setup) but not for production. Use PostgreSQL, MySQL, etc. for production.' },
  { id: 'w7q8', week: 7, type: 'multiple_choice', question: 'What does @GeneratedValue(strategy = GenerationType.IDENTITY) do?', options: ['Generates a UUID', 'Auto-increments the ID using database identity column', 'Creates a sequence', 'Does nothing'], correctAnswer: 'Auto-increments the ID using database identity column', explanation: 'IDENTITY strategy relies on the database\'s auto-increment feature to generate primary key values.' },
  { id: 'w7q9', week: 7, type: 'fill_blank', question: 'SQL GROUP BY is used with _____ functions like COUNT, SUM, AVG.', correctAnswer: 'aggregate', explanation: 'GROUP BY groups rows, then aggregate functions (COUNT, SUM, AVG, MIN, MAX) compute values for each group.' },
  { id: 'w7q10', week: 7, type: 'true_false', question: '@DataJpaTest loads only the JPA/repository layer for testing.', correctAnswer: 'True', explanation: '@DataJpaTest is a test slice that auto-configures only JPA components, an embedded DB, and repositories — not the full context.' },
  { id: 'w7q11', week: 7, type: 'multiple_choice', question: 'What is the N+1 query problem?', options: ['Running N+1 migration scripts', 'One query to fetch parents, then N separate queries for each child', 'Having N+1 database tables', 'N+1 test failures'], correctAnswer: 'One query to fetch parents, then N separate queries for each child', explanation: 'N+1 occurs when fetching a collection: 1 query for the parent entities, then N queries to lazy-load each child. Fix with JOIN FETCH or @EntityGraph.' },
  { id: 'w7q12', week: 7, type: 'multiple_choice', question: 'What annotation creates a custom JPQL query?', options: ['@SQL', '@NativeQuery', '@Query', '@CustomQuery'], correctAnswer: '@Query', explanation: '@Query("SELECT u FROM User u WHERE u.email = ?1") defines custom JPQL queries on repository methods.' },
  { id: 'w7q13', week: 7, type: 'true_false', question: 'An index on a database column speeds up read queries but slows down writes.', correctAnswer: 'True', explanation: 'Indexes speed up SELECT queries but add overhead to INSERT/UPDATE/DELETE operations because the index must be maintained.' },
  { id: 'w7q14', week: 7, type: 'fill_blank', question: 'The JPA annotation for a many-to-one relationship is @_____.', correctAnswer: 'ManyToOne', explanation: '@ManyToOne maps the "many" side of a relationship. The entity with @ManyToOne typically has the foreign key column.' },
  { id: 'w7q15', week: 7, type: 'multiple_choice', question: 'What is a LEFT JOIN?', options: ['Returns only matching rows', 'Returns all rows from the left table, with NULLs for non-matching right rows', 'Returns all rows from both tables', 'Joins tables by primary key only'], correctAnswer: 'Returns all rows from the left table, with NULLs for non-matching right rows', explanation: 'LEFT JOIN preserves all rows from the left table. Unmatched rows from the right table appear as NULL.' },
  { id: 'w7q16', week: 7, type: 'true_false', question: 'Flyway migration files should be named with a version number like V1__create_users.sql.', correctAnswer: 'True', explanation: 'Flyway uses versioned naming: V1__description.sql, V2__description.sql, etc. The version number determines execution order.' },
  { id: 'w7q17', week: 7, type: 'multiple_choice', question: 'What is cascade = CascadeType.ALL?', options: ['Deletes only the parent', 'Applies all operations (persist, merge, remove, etc.) to child entities', 'Prevents deletion', 'Only cascades reads'], correctAnswer: 'Applies all operations (persist, merge, remove, etc.) to child entities', explanation: 'CascadeType.ALL means when you persist, merge, or remove the parent entity, the same operation applies to its children.' },
  { id: 'w7q18', week: 7, type: 'code_snippet', question: 'What does this Flyway migration do?', codeSnippet: '-- V1__create_users_table.sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  email VARCHAR(255) NOT NULL UNIQUE,\n  name VARCHAR(100) NOT NULL\n);', options: ['Drops the users table', 'Creates a users table with id, email, and name columns', 'Inserts sample data', 'Modifies an existing table'], correctAnswer: 'Creates a users table with id, email, and name columns', explanation: 'This is an initial migration creating the users table with an auto-incrementing ID, unique email, and name.' },
  { id: 'w7q19', week: 7, type: 'fill_blank', question: 'JPQL stands for Java Persistence _____ Language.', correctAnswer: 'Query', explanation: 'JPQL (Java Persistence Query Language) is an object-oriented query language that queries entities, not tables directly.' },
  { id: 'w7q20', week: 7, type: 'true_false', question: 'Spring Data JPA can derive queries from method names like findByEmailContaining().', correctAnswer: 'True', explanation: 'Spring Data parses method names and auto-generates queries. findByEmailContaining generates a LIKE query for partial matches.' },
];

